{"judgments": [
 {"clause_id": "c001", "issues": [
   {"issue": "The provision is hortatory (\"share the responsibility\", \"requires the cooperation of all\") and states no rule capable of application, so its operative content is uncertain.", "type": 1, "prob": 0.13},
   {"issue": null, "type": 2, "prob": 0.05}
 ]},
 {"clause_id": "c002", "issues": [
   {"issue": "The prohibited behaviors are single undefined words — \"intimidates\", \"harasses or bullies\", \"invades personal privacy\", \"endangers the health, safety, or welfare\" — each of which is reasonably susceptible to broad and narrow readings when applied to particular conduct.", "type": 1, "prob": 0.58},
   {"issue": "2.1.f permits campus restriction or emergency suspension merely because a student is \"involved in such an incident\", whereas Section 22.2 forbids altering a student's status pending final action \"except for reasons of imminent danger\".", "type": 2, "prob": 0.28}
 ]},
 {"clause_id": "c003", "issues": [
   {"issue": "\"Comply with instructions of University officials\" sets no limit on which instructions bind a student, so its reach cannot be measured from the text.", "type": 1, "prob": 0.17},
   {"issue": null, "type": 2, "prob": 0.06}
 ]},
 {"clause_id": "c004", "issues": [
   {"issue": null, "type": 1, "prob": 0.09},
   {"issue": null, "type": 2, "prob": 0.07}
 ]},
